package dbr

import (
	"github.com/mailru/dbr/dialect"

	"testing"

	"github.com/stretchr/testify/assert"
)

func TestTransactionCommit(t *testing.T) {
	for _, sess := range testSession {
		tx, err := sess.Begin()
		assert.NoError(t, err)
		defer tx.RollbackUnlessCommitted()

		id := nextID()

		result, err := tx.InsertInto("dbr_people").Columns("id", "name", "email").Values(id, "Barack", "obama@whitehouse.gov").Exec()
		assert.NoError(t, err)

		rowsAffected, err := result.RowsAffected()
		// not all drivers supports RowsAffected
		if err == nil {
			assert.EqualValues(t, 1, rowsAffected)
		}

		err = tx.Commit()
		assert.NoError(t, err)

		var person person
		err = tx.Select("*").From("dbr_people").Where(Eq("id", id)).LoadStruct(&person)
		assert.Error(t, err)
	}
}

func TestTransactionRollback(t *testing.T) {
	for _, sess := range testSession {
		if sess.Dialect == dialect.ClickHouse {
			// clickhouse does not support transactions
			continue
		}
		tx, err := sess.Begin()
		assert.NoError(t, err)
		defer tx.RollbackUnlessCommitted()

		id := nextID()

		result, err := tx.InsertInto("dbr_people").Columns("id", "name", "email").Values(id, "Barack", "obama@whitehouse.gov").Exec()
		assert.NoError(t, err)

		rowsAffected, err := result.RowsAffected()
		assert.NoError(t, err)
		assert.EqualValues(t, 1, rowsAffected)

		err = tx.Rollback()
		assert.NoError(t, err)

		var person person
		err = tx.Select("*").From("dbr_people").Where(Eq("id", id)).LoadStruct(&person)
		assert.Error(t, err)
	}
}

package dbr

import (
	"context"
	"database/sql"
)

// Tx is a transaction for the given Session
type Tx struct {
	EventReceiver
	Dialect Dialect
	*sql.Tx
	ctx context.Context
}

// Begin creates a transaction for the given session
func (sess *Session) Begin() (*Tx, error) {
	return sess.BeginWithOpts(&sql.TxOptions{})
}

// BeginWithOpts creates a transaction for the given section with ability to set TxOpts
func (sess *Session) BeginWithOpts(opts *sql.TxOptions) (*Tx, error) {
	tx, err := sess.beginTx(opts)
	if err != nil {
		return nil, sess.EventErr("dbr.begin.error", err)
	}
	sess.Event("dbr.begin")

	return &Tx{
		EventReceiver: sess.EventReceiver,
		Dialect:       sess.Dialect,
		Tx:            tx,
		ctx:           sess.ctx,
	}, nil
}

// Commit finishes the transaction
func (tx *Tx) Commit() error {
	err := tx.Tx.Commit()
	if err != nil {
		return tx.EventErr("dbr.commit.error", err)
	}
	tx.Event("dbr.commit")
	return nil
}

// Rollback cancels the transaction
func (tx *Tx) Rollback() error {
	err := tx.Tx.Rollback()
	if err != nil {
		return tx.EventErr("dbr.rollback", err)
	}
	tx.Event("dbr.rollback")
	return nil
}

// RollbackUnlessCommitted rollsback the transaction unless it has already been committed or rolled back.
// Useful to defer tx.RollbackUnlessCommitted() -- so you don't have to handle N failure cases
// Keep in mind the only way to detect an error on the rollback is via the event log.
func (tx *Tx) RollbackUnlessCommitted() {
	err := tx.Tx.Rollback()
	if err == sql.ErrTxDone {
		// ok
	} else if err != nil {
		tx.EventErr("dbr.rollback_unless_committed", err)
	} else {
		tx.Event("dbr.rollback")
	}
}

