package dbr

import (
	"context"
	"database/sql"
	"testing"

	"github.com/mailru/dbr/dialect"
	"github.com/stretchr/testify/assert"
)

func TestContextCancel(t *testing.T) {
	// context support is implemented for PostgreSQL
	for _, sess := range testSession {
		if sess.Dialect == dialect.SQLite3 {
			continue
		}
		checkSessionContext(t, postgresSession.Connection)
		if sess.Dialect != dialect.ClickHouse {
			checkTxQueryContext(t, postgresSession.Connection)
			checkTxExecContext(t, postgresSession.Connection)
		}
	}
}

func checkSessionContext(t *testing.T, conn *Connection) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	sess := conn.NewSessionContext(ctx, nil)
	_, err := sess.SelectBySql("SELECT 1").ReturnInt64()
	assert.EqualError(t, err, "context canceled")
	_, err = sess.Update("dbr_people").Where(Eq("id", 1)).Set("name", "jonathan1").Exec()
	assert.EqualError(t, err, "context canceled")
	_, err = sess.Begin()
	assert.EqualError(t, err, "context canceled")
}

func checkTxQueryContext(t *testing.T, conn *Connection) {
	ctx, cancel := context.WithCancel(context.Background())
	sess := conn.NewSessionContext(ctx, nil)
	tx, err := sess.Begin()
	if !assert.NoError(t, err) {
		cancel()
		return
	}
	cancel()
	_, err = tx.SelectBySql("SELECT 1").ReturnInt64()
	assert.EqualError(t, err, "context canceled")
	err = tx.Rollback()
	// context cancel may cause transaction rollback automatically
	assert.True(t, err == nil || err == sql.ErrTxDone)
}

func checkTxExecContext(t *testing.T, conn *Connection) {
	ctx, cancel := context.WithCancel(context.Background())
	sess := conn.NewSessionContext(ctx, nil)
	tx, err := sess.Begin()
	if !assert.NoError(t, err) {
		cancel()
		return
	}
	_, err = tx.Update("dbr_people").Where(Eq("id", 1)).Set("name", "jonathan1").Exec()
	assert.NoError(t, err)
	cancel()
	assert.EqualError(t, tx.Commit(), "context canceled")
}

package dbr

import (
	"testing"

	"github.com/mailru/dbr/dialect"
	"github.com/stretchr/testify/assert"
)

func TestCondition(t *testing.T) {
	for _, test := range []struct {
		cond  Builder
		query string
		value []interface{}
	}{
		{
			cond:  Eq("col", 1),
			query: "`col` = ?",
			value: []interface{}{1},
		},
		{
			cond:  Eq("col", nil),
			query: "`col` IS NULL",
			value: nil,
		},
		{
			cond:  Eq("col", []int{}),
			query: "0",
			value: nil,
		},
		{
			cond:  Eq("col", map[int]int{}),
			query: "0",
			value: nil,
		},
		{
			cond:  Eq("col", []int{1}),
			query: "`col` IN ?",
			value: []interface{}{[]int{1}},
		},
		{
			cond:  Eq("col", map[int]int{1: 2}),
			query: "`col` IN ?",
			value: []interface{}{map[int]int{1: 2}},
		},
		{
			cond:  Neq("col", 1),
			query: "`col` != ?",
			value: []interface{}{1},
		},
		{
			cond:  Neq("col", nil),
			query: "`col` IS NOT NULL",
			value: nil,
		},
		{
			cond:  Neq("col", []int{}),
			query: "1",
			value: nil,
		},
		{
			cond:  Neq("col", []int{1}),
			query: "`col` NOT IN ?",
			value: []interface{}{[]int{1}},
		},
		{
			cond:  Neq("col", map[int]int{1: 2}),
			query: "`col` NOT IN ?",
			value: []interface{}{map[int]int{1: 2}},
		},
		{
			cond:  Gt("col", 1),
			query: "`col` > ?",
			value: []interface{}{1},
		},
		{
			cond:  Gte("col", 1),
			query: "`col` >= ?",
			value: []interface{}{1},
		},
		{
			cond:  Lt("col", 1),
			query: "`col` < ?",
			value: []interface{}{1},
		},
		{
			cond:  Lte("col", 1),
			query: "`col` <= ?",
			value: []interface{}{1},
		},
		{
			cond:  And(Lt("a", 1), Or(Gt("b", 2), Neq("c", 3))),
			query: "(`a` < ?) AND ((`b` > ?) OR (`c` != ?))",
			value: []interface{}{1, 2, 3},
		},
	} {
		buf := NewBuffer()
		err := test.cond.Build(dialect.MySQL, buf)
		assert.NoError(t, err)
		assert.Equal(t, test.query, buf.String())
		assert.Equal(t, test.value, buf.Value())
	}
}

package dbr

import (
	"reflect"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
)

type innerTestStruct struct {
	InnerTime    time.Time
	InnerNonTime int64
}

type testStruct struct {
	innerTestStruct
	Time          time.Time
	Inner         innerTestStruct
	InnerPtr      *innerTestStruct
	InnerSlice    []innerTestStruct
	InnerSlicePtr []*innerTestStruct
	InnerMap      map[int]*innerTestStruct
}

func TestChangeTimezone(t *testing.T) {
	location := "America/New_York"

	v := testStruct{
		innerTestStruct: innerTestStruct{
			InnerTime: time.Date(2020, 1, 20, 8, 0, 0, 0, time.UTC),
		},
		Time: time.Date(2020, 1, 21, 9, 0, 0, 0, time.UTC),
		Inner: innerTestStruct{
			InnerTime: time.Date(2020, 1, 22, 10, 0, 0, 0, time.UTC),
		},
		InnerPtr: &innerTestStruct{
			InnerTime: time.Date(2020, 1, 23, 11, 0, 0, 0, time.UTC),
		},
		InnerSlice: []innerTestStruct{
			{InnerTime: time.Date(2020, 1, 24, 12, 0, 0, 0, time.UTC)},
			{InnerTime: time.Date(2020, 1, 25, 13, 0, 0, 0, time.UTC)},
		},
		InnerSlicePtr: []*innerTestStruct{
			{InnerTime: time.Date(2020, 1, 26, 14, 0, 0, 0, time.UTC)},
			{InnerTime: time.Date(2020, 1, 27, 15, 0, 0, 0, time.UTC)},
		},
		InnerMap: map[int]*innerTestStruct{
			1: {InnerTime: time.Date(2020, 1, 28, 16, 0, 0, 0, time.UTC)},
			2: {InnerTime: time.Date(2020, 1, 28, 16, 0, 0, 0, time.UTC)},
		},
	}

	b := &selectBuilder{}
	l, _ := time.LoadLocation(location)
	b.InTimezone(l)
	b.changeTimezone(reflect.ValueOf(&v))

	assert.Equal(t, "America/New_York", v.InnerTime.Location().String())
	assert.Equal(t, "America/New_York", v.Time.Location().String())
	assert.Equal(t, "America/New_York", v.Inner.InnerTime.Location().String())
	assert.Equal(t, "America/New_York", v.InnerPtr.InnerTime.Location().String())
	for _, tt := range v.InnerSlice {
		assert.Equal(t, "America/New_York", tt.InnerTime.Location().String())
	}

	for _, tt := range v.InnerSlicePtr {
		assert.Equal(t, "America/New_York", tt.InnerTime.Location().String())
	}

	for _, tt := range v.InnerMap {
		assert.Equal(t, "America/New_York", tt.InnerTime.Location().String())
	}
}

package dbr

import (
	"database/sql"
	"database/sql/driver"
	"fmt"
	"reflect"
	"testing"

	"github.com/DATA-DOG/go-sqlmock"
	"github.com/mailru/dbr/dialect"
	"github.com/stretchr/testify/assert"
)

func TestLoad(t *testing.T) {
	type testStruct struct {
		A string
	}

	testcases := []struct {
		columns  []string
		expected interface{}
	}{
		{[]string{"a"}, "a"},
		{[]string{"a"}, []string{"a"}},
		{[]string{"a"}, testStruct{"a"}},
		{[]string{"a"}, &testStruct{"a"}},
		{[]string{"a"}, []testStruct{{"a"}}},
		{[]string{"a"}, []*testStruct{{"a"}}},
		{[]string{"a", "b"}, map[string]interface{}{"a": "a", "b": "b"}},
		{[]string{"a", "b"}, &map[string]interface{}{"a": "a", "b": "b"}},
		{[]string{"a", "b"}, []map[string]interface{}{{"a": "a", "b": "b"}}},
	}

	for _, tc := range testcases {
		var values []driver.Value
		session, dbmock := newSessionMock()
		for _, c := range tc.columns {
			values = append(values, c)
		}
		rows := sqlmock.NewRows(tc.columns).AddRow(values...)
		dbmock.ExpectQuery("SELECT .+").WillReturnRows(rows)
		v := reflect.New(reflect.TypeOf(tc.expected)).Elem().Addr().Interface()
		session.Select(tc.columns...).From("table").Load(v)
		assert.Equal(t, tc.expected, reflect.Indirect(reflect.ValueOf(v)).Interface())
	}
}

func TestLoadWithBytesValue(t *testing.T) {
	var values []driver.Value
	columns := []string{"fieldname"}
	value := []byte("fieldvalue")
	session, dbmock := newSessionMock()
	values = append(values, value)
	rows := sqlmock.NewRows(columns).AddRow(values...)
	dbmock.ExpectQuery("SELECT .+").WillReturnRows(rows)
	v := reflect.New(reflect.TypeOf(map[string]interface{}(nil))).Elem().Addr().Interface()
	session.Select(columns...).From("table").Load(v)
	value[0] = byte('a')
	assert.Equal(t, map[string]interface{}{"fieldname": []byte("fieldvalue")},
		reflect.Indirect(reflect.ValueOf(v)).Interface())
}

func BenchmarkLoad(b *testing.B) {
	session, dbmock := newSessionMock()
	rows := sqlmock.NewRows([]string{"a", "b", "c"})
	for i := 0; i < 100; i++ {
		rows = rows.AddRow(1, 2, 3)
	}
	dbmock.ExpectQuery("SELECT a, b, c FROM table").WillReturnRows(rows)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		r := make([]struct {
			A int `db:"a"`
			B int `db:"b"`
			C int
			D int `db:"-"`
			e int
			F int `db:"f"`
			G int `db:"g"`
			H int `db:"h"`
			i int
			j int
		}, 0, 100)
		session.Select("a", "b", "c").From("table").LoadStructs(&r)
	}
}

func newSessionMock() (SessionRunner, sqlmock.Sqlmock) {
	db, m, err := sqlmock.New()
	if err != nil {
		panic(err)
	}
	conn := Connection{DBConn: db, Dialect: dialect.MySQL, EventReceiver: nullReceiver}
	return conn.NewSession(nil), m
}

